prompt --application/shared_components/user_interface/lovs/bill_booking_id
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(7462111957872235)
,p_lov_name=>'BILL_BOOKING_ID'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select bm.booking_Id,ci.booking_m_id',
'from   check_out c, booking_m bm, check_in ci',
'where  c.check_in_id = ci.check_in_id',
'and    ci.booking_m_id = bm.booking_m_id',
'and    ci.booking_m_id not in (select booking_m_Id',
'                              from   bill)',
'order by booking_Id desc ;'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_return_column_name=>'BOOKING_M_ID'
,p_display_column_name=>'BOOKING_ID'
,p_group_sort_direction=>'ASC'
,p_default_sort_direction=>'ASC'
);
end;
