prompt --application/shared_components/reports/report_queries/monthly_income
begin
wwv_flow_imp_shared.create_shared_query(
 p_id=>wwv_flow_imp.id(8572286823347529)
,p_name=>'Monthly Income'
,p_query_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  SELECT TO_CHAR(booking_m_date, ''YYYY-MM'') AS month,SUM(ADVANCED_PAID) AS total_advance_paid,',
'         SUM(net_pay_bill) AS total_net_pay_bill',
'  FROM   booking_m bm,bill b',
'  where  bm.booking_m_id = b.booking_m_id  ',
'  group  by TO_CHAR(booking_m_date, ''YYYY-MM'')  ',
'  order  by TO_CHAR(booking_m_date, ''YYYY-MM''); '))
,p_format=>'PDF'
,p_output_file_name=>'Monthly Income'
,p_content_disposition=>'ATTACHMENT'
);
end;
/
prompt --application/shared_components/reports/report_queries/daily_expense
begin
wwv_flow_imp_shared.create_shared_query(
 p_id=>wwv_flow_imp.id(9484028829830270)
,p_name=>'Daily_Expense'
,p_query_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  ed.EXPENSE_M_ID,EXPENSE_TYPE_NAME,EXPENSE_AMOUNT,BRANCH_NAME,EXPENSE_DATE,Expense_by',
'from    expense_m em,EXPENSE_D ed,EXPENSE_TYPE et,BRANCH b',
'where   ed.EXPENSE_M_ID = em.EXPENSE_M_ID',
'and     ed.EXPENSE_TYPE_id = et.EXPENSE_TYPE_id',
'and     em.BRANCH_ID = b.BRANCH_ID'))
,p_report_layout_id=>wwv_flow_imp.id(12407031291875250)
,p_format=>'PDF'
,p_output_file_name=>'Daily_Expense'
,p_content_disposition=>'INLINE'
);
wwv_flow_imp_shared.create_shared_query_stmnt(
 p_id=>wwv_flow_imp.id(12407440551876425)
,p_shared_query_id=>wwv_flow_imp.id(9484028829830270)
,p_sql_statement=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  ed.EXPENSE_M_ID,EXPENSE_TYPE_NAME,EXPENSE_AMOUNT,BRANCH_NAME,EXPENSE_DATE,Expense_by',
'from    expense_m em,EXPENSE_D ed,EXPENSE_TYPE et,BRANCH b',
'where   ed.EXPENSE_M_ID = em.EXPENSE_M_ID',
'and     ed.EXPENSE_TYPE_id = et.EXPENSE_TYPE_id',
'and     em.BRANCH_ID = b.BRANCH_ID',
'and     to_date(em.EXPENSE_DATE,''MM/DD/YYYY'') like to_date(:P63_EXPENSE_DATE,''MM/DD/YYYY'')'))
);
end;
