,p_name=>'Monthly_Expense'
,p_query_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  ed.EXPENSE_M_ID,EXPENSE_TYPE_NAME,EXPENSE_AMOUNT,BRANCH_NAME,to_char(em.EXPENSE_DATE,''Month/YYYY'') EXPENSE_DATE,Expense_by',
'from    expense_m em,EXPENSE_D ed,EXPENSE_TYPE et,BRANCH b',
'where   ed.EXPENSE_M_ID = em.EXPENSE_M_ID',
'and     ed.EXPENSE_TYPE_id = et.EXPENSE_TYPE_id',
'and     em.BRANCH_ID = b.BRANCH_ID'))
,p_report_layout_id=>wwv_flow_imp.id(12407848605884971)
,p_format=>'PDF'
,p_output_file_name=>'Monthly_Expense'
,p_content_disposition=>'INLINE'
);
wwv_flow_imp_shared.create_shared_query_stmnt(
 p_id=>wwv_flow_imp.id(12408802309902817)
,p_shared_query_id=>wwv_flow_imp.id(10204954358951656)
,p_sql_statement=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  ed.EXPENSE_M_ID,EXPENSE_TYPE_NAME,EXPENSE_AMOUNT,BRANCH_NAME,to_char(EXPENSE_DATE,''fmMonth-YYYY'') EXPENSE_DATE,Expense_by',
'from    expense_m em,EXPENSE_D ed,EXPENSE_TYPE et,BRANCH b',
