,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'fa-search<br/>',
'fa-calendar-search<br/>',
'fa-cloud-search<br/>',
'fa-database-search<br/>',
'fa-envelope-search<br/>',
'fa-file-search<br/>',
