,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function($) ',
'{',
' function update(model) ',
' {',
' var salKey = model.getFieldKey("TOTAL_RENT"),',
' total = 0;',
' console.log(">> starting sum TOTAL_RENT column")',
' model.forEach(function(record, index, id) ',
' {',
' var sal = parseFloat(record[salKey]), ',
' meta = model.getRecordMetadata(id);',
' if (!isNaN(sal) && !meta.deleted && !meta.agg) ',
' {',
' total += sal;',
' }',
' });',
' console.log(">> setting sum SAL column to " + total)',
' $s("P64_TOTAL_AMOUNT", total);',
' }',
' $(function() ',
' {',
' $("#nur").on("interactivegridviewmodelcreate", function(event, ui) ',
' {',
' var sid,',
' model = ui.model;',
' if ( ui.viewId === "grid" ) ',
' {',
' sid = model.subscribe( ',
' {',
' onChange: function(type, change) ',
'{',
' console.log(">> model changed ", type, change);',
' if ( type === "set" ) ',
' {',
' ',
' if (change.field === "TOTAL_RENT" ) ',
' {',
' update( model );',
' }',
' } else if (type !== "move" && type !== "metaChange") ',
' {',
' ',
' update( model );',
' }',
' },',
' progressView: $("#P64_TOTAL_AMOUNT") ',
' } );',
' update( model );',
' model.fetchAll(function() {});',
' }',
' });',
' });',
' })(apex.jQuery);'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'02'
,p_last_updated_by=>'IMRAN'
,p_last_upd_yyyymmddhh24miss=>'20240516141148'
