'    (substr("USERNAME", 1, 50)||( case when length("USERNAME") > 50 then ''...'' else '''' end )) LIST_TITLE,',
'    (substr("ACTION_USER", 1, 50)||( case when length("ACTION_USER") > 50 then ''...'' else '''' end )) LIST_TEXT,',
'    null LIST_BADGE',
'from "MENU_ACCESS_M" x',
'where (:P65_SEARCH is null',
'        or upper(x."USERNAME") like ''%''||upper(:P65_SEARCH)||''%''',
'        or upper(x."ACTION_USER") like ''%''||upper(:P65_SEARCH)||''%''',
'    )',
'order by "USERNAME"'))
,p_ajax_enabled=>'Y'
