wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(8259869716496914)
,p_process_sequence=>60
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'cancelation fee Process'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_hours_diff NUMBER;',
'    v_cancel_fee NUMBER;',
'    v_total_amount NUMBER; -- grand total from booking table',
'    v_booking_m_date DATE; -- booking date from booking table',
'    v_booking_m_id NUMBER := :P75_BOOKING_m_ID; -- booking id',
'BEGIN',
'    -- Assume you have the booking id and fetch the grand total and booking date for that booking',
'    SELECT grant_total, booking_m_date INTO v_total_amount, v_booking_m_date FROM booking_m WHERE booking_m_id = v_booking_m_id;',
'',
'    -- Calculate the difference in hours between booking time and cancellation time',
'    -- Replace SYSDATE with your cancellation time',
'    v_hours_diff := (SYSDATE - v_booking_m_date) * 24;',
'',
'    -- Check if the cancellation is before 24 hours',
'    IF v_hours_diff < 24 THEN',
'        v_cancel_fee := v_total_amount * 0.10; -- 10% of the total amount',
'    ELSE',
'        v_cancel_fee := v_total_amount * 0.20; -- 20% of the total amount',
'    END IF;',
'',
'    -- Now you can use v_cancel_fee as your cancellation fee',
'    -- Update the cancellation table with the calculated fee',
'    UPDATE cancellation SET cancellation_fee = v_cancel_fee WHERE booking_m_id = v_booking_m_id;',
'',
'    COMMIT;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'      DBMS_OUTPUT.PUT_LINE(''An error occurred: '' || SQLERRM);',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(8209952955244421)
,p_internal_uid=>8259869716496914
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(8259907247496915)
,p_process_sequence=>70
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Refund Amount'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_ADVANCED_PAID NUMBER; -- advance paid from booking table',
'    v_cancellation_fee NUMBER; -- cancellation fee from cancellation table',
'    v_refund_amount NUMBER; -- refund amount',
'    v_booking_m_id NUMBER; -- booking id',
'BEGIN',
'    -- Assume you have the booking id and fetch the advance paid and cancellation fee for that booking',
'    SELECT ADVANCED_PAID, cancellation_fee INTO v_ADVANCED_PAID, v_cancellation_fee FROM booking_m JOIN cancellation ON booking_m.booking_m_id = cancellation.booking_m_id WHERE booking_m.booking_m_id = v_booking_m_id;',
'',
'    -- Calculate the refund amount',
'    v_refund_amount := v_ADVANCED_PAID - v_cancellation_fee;',
'',
'    -- Now you can use v_refund_amount as your refund amount',
'    -- Add your code here to update the database or return the refund amount',
'',
'    DBMS_OUTPUT.PUT_LINE(''Refund Amount: '' || v_refund_amount);',
'EXCEPTION',
'    WHEN OTHERS THEN',
'      DBMS_OUTPUT.PUT_LINE(''An error occurred: '' || SQLERRM);',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>8259907247496915
);
